"""Render the bounded, manually inspected primary-source evidence matrix."""
from pathlib import Path
import json

P = Path(__file__).resolve().parent
index = json.loads((P / "code-source-index.json").read_text())

def code(repo, path, symbols, finding):
    row = next(x for x in index["files"] if x["repo"] == repo and x["path"] == path)
    return {"repo": repo, "commit": row["commit"], "path": path,
            "url": row["url"], "sha256": row["sha256"],
            "symbols": symbols, "inspection": finding, "execution": "NOT_RUN"}

